-- Rollback-only integration assertions; no real student data is changed.
begin;
do $$ declare test_actor uuid:=gen_random_uuid(); r1 jsonb; r2 jsonb; d date:=(now() at time zone 'Europe/Istanbul')::date; i int;
begin
 insert into public.students(id,username,password_hash,status,energy,energy_max,energy_updated_at,streak) values(test_actor,'daily_gift_check_'||substr(test_actor::text,1,8),'unused-test-hash','approved',10,25,now(),99);
 r1:=public.dm_daily_gift(test_actor,false);
 assert (r1->>'streak')::int=1 and (r1->>'eklenen')::int=0 and not (r1->>'alreadyClaimed')::boolean, 'status never awards energy or trusts old numeric streak';
 r1:=public.dm_daily_energy_bonus(test_actor);r2:=public.dm_daily_energy_bonus(test_actor);
 assert (r1->>'eklenen')::int=1 and (r1->>'rewardAmount')::int=1, 'first day earns one';
 assert (r2->>'eklenen')::int=0 and (r2->>'enerjiKalan')::int=11, 'repeat claim cannot earn again';
 assert (select count(*) from public.energy_transactions where student_id=test_actor and reason='gunluk')=1, 'one ledger entry';
 delete from public.extra_data where student_id=test_actor;delete from public.energy_transactions where student_id=test_actor;
 update public.students set energy=0 where id=test_actor;
 for i in 1..2 loop insert into public.extra_data(student_id,key_name,value) values(test_actor,'member_login:'||(d-i)::text,'{}');end loop;
 r1:=public.dm_daily_energy_bonus(test_actor);
 assert (r1->>'streak')::int=3 and (r1->>'eklenen')::int=3, 'third consecutive day earns three';
 assert r1->'claimedDays' @> '[3]'::jsonb, 'calendar includes confirmed current claim';
 delete from public.extra_data where student_id=test_actor;delete from public.energy_transactions where student_id=test_actor;
 update public.students set energy=0 where id=test_actor;
 for i in 1..7 loop insert into public.extra_data(student_id,key_name,value) values(test_actor,'member_login:'||(d-i)::text,'{}');end loop;
 r1:=public.dm_daily_energy_bonus(test_actor);
 assert (r1->>'streak')::int=8 and (r1->>'eklenen')::int=8 and (r1->>'windowStart')::int=8, 'calendar advances beyond seven without resetting rewards';
 delete from public.extra_data where student_id=test_actor;delete from public.energy_transactions where student_id=test_actor;
 insert into public.extra_data(student_id,key_name,value) values(test_actor,'member_login:'||(d-2)::text,'{}');
 r1:=public.dm_daily_gift(test_actor,false);assert (r1->>'streak')::int=1, 'unprotected missed day restarts at one';
 insert into public.extra_data(student_id,key_name,value) values(test_actor,'streak_shield:'||(d-1)::text,'{}');
 r1:=public.dm_daily_gift(test_actor,false);assert (r1->>'streak')::int=3, 'earned streak protection still applies';
 update public.students set energy=24 where id=test_actor;
 r1:=public.dm_daily_energy_bonus(test_actor);assert (r1->>'eklenen')::int=1 and (r1->>'enerjiKalan')::int=25 and (r1->>'rewardAmount')::int=3, 'respect plan energy capacity and report actual credit';
 r2:=public.dm_daily_energy_bonus(test_actor);assert (r2->>'eklenen')::int=0, 'capped reward cannot be claimed again';
 delete from public.extra_data where student_id=test_actor;delete from public.energy_transactions where student_id=test_actor;
 insert into public.energy_transactions(student_id,change_amount,balance_after,reason,created_at) values(test_actor,5,25,'gunluk',d::timestamp at time zone 'Europe/Istanbul');
 r1:=public.dm_daily_energy_bonus(test_actor);assert (r1->>'eklenen')::int=0 and (r1->>'alreadyClaimed')::boolean, 'honor pre-upgrade Istanbul-day claims';
 assert r1->>'day'=d::text, 'server Istanbul date';
 assert not has_function_privilege('anon','public.dm_daily_gift(uuid,boolean)','EXECUTE') and not has_function_privilege('authenticated','public.dm_daily_gift(uuid,boolean)','EXECUTE'), 'direct public reward RPC stays private';
end $$;
select 'status, first/third/eighth day, repeated claim, shield, capacity, legacy and permissions passed' as verification;
rollback;
